loop:
	VMOVDQU (BX), Y0
	VMOVDQU 32(BX), Y1
	VPSHUFB Y8, Y0, Y2
	VPSHUFB Y8, Y1, Y3
	VPUNPCKHQDQ Y3, Y2, Y4
	VPUNPCKLQDQ Y3, Y2, Y5
	VMOVDQU Y4, (AX)
	VMOVDQU Y5, 32(AX)
	ADDQ $64, BX
	ADDQ $64, AX
	SUBQ $64, CX
	JNZ loop
	VZEROUPPER
	RET

TEXT ·shufFinishAVX2(SB), NOSPLIT, $0-24
	MOVQ dst+0(FP), AX
	MOVQ src+8(FP), BX
	MOVQ n+16(FP), CX
loop:
