	VMOVDQU 32(BX), Y1
	VPUNPCKLBW Y0, Y1, Y2
	VPUNPCKHBW Y0, Y1, Y3
	VMOVDQU Y2, (AX)
	VMOVDQU Y3, 32(AX)
	ADDQ $64, BX
	ADDQ $64, AX
	SUBQ $64, CX
	JNZ loop
	VZEROUPPER
	RET

