TEXT ·xorSSE(SB), NOSPLIT, $0-24
	MOVQ dst+0(FP), AX
	MOVQ src+8(FP), BX
	MOVQ n+16(FP), CX
	CMPQ CX, $32
	JLT tail
loop:
	MOVOU 0(BX), X0
	MOVOU 0(AX), X2
	PXOR X2, X0
	MOVOU X0, 0(AX)
	MOVOU 16(BX), X1
	MOVOU 16(AX), X3
	PXOR X3, X1
	MOVOU X1, 16(AX)
	ADDQ $32, AX
	ADDQ $32, BX
	SUBQ $32, CX
	CMPQ CX, $32
	JGE loop
tail:
	TESTQ CX, CX
	JZ done
	MOVOU (BX), X0
	MOVOU (AX), X2
	PXOR X2, X0
	MOVOU X0, (AX)
done:
	RET

TEXT ·xorAVX2(SB), NOSPLIT, $0-24
	MOVQ dst+0(FP), AX
	MOVQ src+8(FP), BX
	MOVQ n+16(FP), CX
	CMPQ CX, $64
	JLT tail
loop:
	VMOVDQU 0(BX), Y0
	VPXOR 0(AX), Y0, Y0
	VMOVDQU Y0, 0(AX)
	VMOVDQU 32(BX), Y1
	VPXOR 32(AX), Y1, Y1
	VMOVDQU Y1, 32(AX)
	ADDQ $64, AX
	ADDQ $64, BX
	SUBQ $64, CX
	CMPQ CX, $64
	JGE loop
tail:
	TESTQ CX, CX
	JZ done
	VMOVDQU (BX), Y0
	VPXOR (AX), Y0, Y0
	VMOVDQU Y0, (AX)
done:
	VZEROUPPER
	RET
